export const a2GeneratedQuestions: MeaningMatchQuestion[] = TOPICS.flatMap((block) =>
  block.rows.map((row) => {
    const [word, meaningTr, partOfSpeech, exampleSentence, exampleTranslation] = row;
    const key = word.toLowerCase();
    const wrongOptions = A2_DISTRACTORS[key] || ["diğer seçenek", "farklı anlam"];
    const collocation = A2_COLLOCATIONS[key];
    const productionPrompt = A2_PRODUCTION_PROMPTS[key];
    return {
      id: `a2-core-${word.replace(/[^a-z]/gi, "-").toLowerCase()}`,
      mode: "MEANING_MATCH" as const,
      level: "A2" as const,
      topic: block.topic,
      word,
      meaning: meaningTr,
      wrongOptions,
      xp: computeXpReward("A2", word),
      difficulty: computeDifficulty("A2", word),
      partOfSpeech,
      exampleSentence,
      exampleTranslation,
      collocation,
      productionPrompt,
      contextNote: `${block.topic} konusu için A2 seviyesi çekirdek kelime.`,
      pronunciation: word,
      hint: `${block.topic} konusundaki kelimeyi seç.`,
      prompt: word,
      answer: meaningTr,
      options: [meaningTr, ...wrongOptions],
    };
  })
);
